//! The pinned identity a node is enrolled against.
//!
//! Two files own it and nothing here invents a digest:
//!
//! - `docs/release-artifacts.json` pins the model revision and the target /
//!   DFlash GGUF SHA-256s.
//! - the container receipt (`muser.gx10-container.receipt.v1`) pins
//!   `adapter_sha256` and the exact `image_id` the producer may run.
//!
//! Tokenizer and template identities come from the canonical GGUF metadata
//! receipt generated by `muser-bench metadata`; they are never hand-entered
//! constants. Context/layout identities remain protocol ABI pins.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use serde::Deserialize;
use sha2::{Digest as _, Sha256};

pub const LLAMA_CPP_COMMIT: &str = "89e0aa6fd362617d9073e0dafc18e41241521572";

use super::Result;

/// DFlash KV geometry the sender pins (`muser_v2_send.py` defaults).
pub const DFLASH_KV_HEADS: i64 = 8;
pub const DFLASH_HEAD_DIM: i64 = 128;

/// The producer's context bound, matching the sealed lane config.
pub const MAX_CONTEXT: i64 = 131_072;

/// Sealed lane identity. `revision` and `model_sha256` are the pin these
/// digests belong to; see the module comment.
struct SealedIdentity {
    revision: &'static str,
    model_sha256: &'static str,
    context_policy_sha256: &'static str,
    target_cache_identity_sha256: &'static str,
}

const SEALED: SealedIdentity = SealedIdentity {
    revision: "a0532f7263ee67f1e0a5f5c5fdcd50dd62fc9aa4",
    model_sha256: "7e9b74b7c8875e9e265695df9613bf6290f2392e479ce740495a129019c488d8",
    context_policy_sha256: "d2913ca9de09e906681fca2addf753b8a561aee41d4383a4f2a791e386186600",
    target_cache_identity_sha256:
        "a3bbd72fc16116322b5c9dc701f155d35349146b2af3e3b8465732b7df1eabd0",
};

#[derive(Debug, Clone, Deserialize)]
pub struct Artifact {
    pub filename: String,
    pub revision: String,
    pub url: String,
    pub bytes: u64,
    pub sha256: String,
}

#[derive(Debug, Clone, Deserialize)]
struct ReleaseArtifactsFile {
    schema: String,
    revision: String,
    artifacts: BTreeMap<String, Artifact>,
}

#[derive(Debug, Deserialize)]
struct ModelMetadataFile {
    schema: String,
    revision: String,
    target_sha256: String,
    tokenizer_hash_algorithm: String,
    tokenizer_metadata_sha256: String,
    chat_template_key: String,
    chat_template_bytes: usize,
    chat_template_sha256: String,
}

/// The pinned release, plus the sealed digests that go with it.
#[derive(Debug, Clone)]
pub struct Release {
    pub revision: String,
    pub target: Artifact,
    pub dflash: Artifact,
    pub tokenizer_sha256: String,
    pub chat_template_sha256: String,
    pub context_policy_sha256: String,
    pub target_cache_identity_sha256: String,
}

impl Release {
    pub fn load(repo_root: &Path) -> Result<Self> {
        let path = repo_root.join("docs/release-artifacts.json");
        let bytes =
            std::fs::read(&path).map_err(|error| format!("read {}: {error}", path.display()))?;
        let file: ReleaseArtifactsFile = serde_json::from_slice(&bytes)
            .map_err(|error| format!("parse {}: {error}", path.display()))?;
        let artifact = |name: &str| -> Result<Artifact> {
            let value = file
                .artifacts
                .get(name)
                .ok_or_else(|| format!("{} has no {name} artifact", path.display()))?;
            validate_sha256(name, &value.sha256)?;
            if value.revision != file.revision
                || value.bytes == 0
                || !value
                    .url
                    .contains(&format!("/resolve/{}/{}", value.revision, value.filename))
            {
                return Err(format!("{name} artifact has an invalid immutable identity"));
            }
            Ok(value.clone())
        };
        let target = artifact("target")?;
        let dflash = artifact("dflash")?;
        let metadata_path = repo_root.join("docs/release-model-metadata.json");
        let metadata: ModelMetadataFile = serde_json::from_slice(
            &std::fs::read(&metadata_path)
                .map_err(|error| format!("read {}: {error}", metadata_path.display()))?,
        )
        .map_err(|error| format!("parse {}: {error}", metadata_path.display()))?;
        if file.schema != "muser.release-artifacts.v2"
            || file.revision != SEALED.revision
            || target.sha256 != SEALED.model_sha256
        {
            return Err(format!(
                "{} pins revision {} / model {} but the sealed lane identity is {} / {}; \
                 a node cannot be enrolled against an identity no producer has agreed to",
                path.display(),
                file.revision,
                target.sha256,
                SEALED.revision,
                SEALED.model_sha256
            ));
        }
        if metadata.schema != "muser.gguf-metadata-identity.v1"
            || metadata.revision != file.revision
            || metadata.target_sha256 != target.sha256
            || metadata.tokenizer_hash_algorithm != "muser.gguf-tokenizer-metadata.v1"
            || metadata.chat_template_key != "tokenizer.chat_template"
            || metadata.chat_template_bytes != 7_167
        {
            return Err(format!(
                "{} is not bound to the pinned target GGUF identity",
                metadata_path.display()
            ));
        }
        validate_sha256("tokenizer metadata", &metadata.tokenizer_metadata_sha256)?;
        validate_sha256("chat template", &metadata.chat_template_sha256)?;
        Ok(Self {
            revision: file.revision,
            target,
            dflash,
            tokenizer_sha256: metadata.tokenizer_metadata_sha256,
            chat_template_sha256: metadata.chat_template_sha256,
            context_policy_sha256: SEALED.context_policy_sha256.into(),
            target_cache_identity_sha256: SEALED.target_cache_identity_sha256.into(),
        })
    }
}

